/**
 * Run Python script.
 *
 * @param scriptPath  Path to Python script.
 * @param args        Arguments of script.
 * @returns           Promise resolving when Python process exits.
 */
async function runPythonScript(scriptPath, args) {
    const command = `python ${scriptPath} ${args.join(' ')}`;
    core_debug(`Running ${command}`);
    return new Promise((resolve, reject) => {
        external_child_process_namespaceObject.exec(command, (error, stdout, stderr) => {
            core_debug(stdout);
            if (error) {
                core_error(`Error executing Python script ${scriptPath}\n${error.message}`);
                reject(error);
            }
            else {
                resolve({ stdout, stderr });
            }
        });
    });
}
/**
 * The main function for the action.
 *
 * @returns {Promise<void>} Resolves when the action is complete.
 */
async function run() {
    try {
        // Get inputs
        core_debug('Get inputs'); // Debug logs are only output if the `ACTIONS_STEP_DEBUG` secret is true
        const inputs = ActionInputs.newFromGitHub();
        // TODO: Make sure OpenModelica and Python 3 are available
        // Clone OpenModelicaLibraryTesting
        core_debug('clone OpenModelicaLibraryTesting');
        await cloneScripts('601633f38aa1ad4c8c0f1d313ecc77aa7ee177aa');
        // Install Python dependencies
        await installPythonDeps(external_path_.join('OpenModelicaLibraryTesting', 'requirements.txt'));
        // Generate config
        core_debug('Generating configuration');
        const confFile = external_path_.resolve(external_path_.join('OpenModelicaLibraryTesting', 'configs', `conf-${inputs.library}.json`));
        const config = new Configuration({
            library: inputs.library,
            libraryVersion: inputs.libraryVersion,
            loadFileCommands: [`loadFile("${inputs.modelicaFile}")`],
            referenceFiles: inputs.referenceFilesDir,
            referenceFileExtension: inputs.referenceFileExtension,
            referenceFileNameDelimiter: inputs.referenceFileNameDelimiter
        });
        await genConfigFile(confFile, [config]);
        info(`conf-${inputs.library}.json:\n\n${external_fs_.readFileSync(confFile, 'utf-8')}`);
        // Run OpenModelicaLibraryTesting scripts
        let msysEnv = '';
        if (external_os_.platform() === 'win32') {
            msysEnv = `--msysEnvironment=${getMSYS()}`;
        }
        const cwd = process.cwd();
        try {
            process.chdir('OpenModelicaLibraryTesting');
            const { stdout } = await runPythonScript('test.py', [
                '--verbose',
                `--branch=${inputs.omcVersion}`,
                '--noclean',
                msysEnv,
                external_path_.join('configs', `conf-${inputs.library}.json`)
            ]);
            // Verify that library has tests
            if (stdout.includes('Not executing any tests.')) {
                notice(`Ensure that ${inputs.library} has models with experiment annotations.`);
                throw new Error('No tests to execute, aborting.');
            }
            await runPythonScript('report.py', [
                `--branch=${inputs.omcVersion}`,
                external_path_.join('configs', `conf-${inputs.library}.json`)
            ]);
            process.chdir(cwd);
        }
        catch (error) {
            process.chdir(cwd);
            throw error;
        }
        // Write summary
        core_debug('Write summary');
        const overviewFile = external_path_.join('OpenModelicaLibraryTesting', `${inputs.library}_${inputs.libraryVersion}.html`);
        const [summary, actionOutputs] = await summaryFromHtmlFile(overviewFile, inputs.pagesRootUrl, inputs.omcVersion, inputs.library, inputs.libraryVersion, inputs.referenceFilesDir !== undefined);
        await summary_summary.addRaw(summary).write();
        core_debug('Set outputs');
        actionOutputs.setOutputs();
        actionOutputs.printInfo();
        if (!inputs.allowFailingTests) {
            actionOutputs.setStatus();
        }
        // Collect HTML files
        core_debug('Collect HTML outputs');
        const htmlArtifactsDir = 'html';
        copyHtmlFilesSync(inputs.library, inputs.libraryVersion, inputs.omcVersion, 'OpenModelicaLibraryTesting', htmlArtifactsDir);
        // Upload artifacts
        core_debug('Upload artifacts');
        await uploadArtifacts(inputs.library, external_path_.join('OpenModelicaLibraryTesting', 'sqlite3.db'), htmlArtifactsDir, inputs.omcVersion);
    }
    catch (error) {
        // Fail the workflow run if an error occurs
        if (error instanceof Error)
            setFailed(error.message);
    }
}

